#include <stdio.h>

int main(void) {
    int arr[6] = {10, 20, 30, 40, 50, 60};
    int *p = arr;
    int *q = arr + 3;
    int sum = 0;

    for (int i = 0; i < 3; i++) {
        *(p + i) = *(p + i) + *(q + i) ;
    }

    for (int i = 0; i < 6; i++) {
        sum += arr[i];
    }

    p = p + 2;
    q = q - 1;

    printf("%d %d\n", *p, *q);
    printf("%d\n", *(p + 1) - *(q - 1));
    printf("%d\n", sum);

    return 0;
}

